# typed: false
# frozen_string_literal: true

# Homebrew formula for CERT-X-GEN (cxg)
# A polyglot execution engine for vulnerability detection
#
# Generated by .github/workflows/update-formula.yml on each cert-x-gen
# release. Edit the workflow, not this file -- a hand edit here is
# overwritten by the next release.
class Cxg < Formula
  desc "Polyglot execution engine for vulnerability detection"
  # @comment -- "brew info / brew home open the cxg product site, cxg.bugb.io"
  homepage "https://cxg.bugb.io"
  version "1.6.1"
  license "Apache-2.0"

  on_macos do
    on_intel do
      url "https://github.com/Bugb-Technologies/cert-x-gen/releases/download/v1.6.1/cxg-darwin-amd64"
      sha256 "983a822bb1aa8891a2f653df7849fe45011d1a45697be2af5a24b6bd715eb6cb"
    end
    on_arm do
      url "https://github.com/Bugb-Technologies/cert-x-gen/releases/download/v1.6.1/cxg-darwin-arm64"
      sha256 "7e868ab0ac265a6b5d854437d753e119bc2b15730c4c4e162c454c7136b5b672"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/Bugb-Technologies/cert-x-gen/releases/download/v1.6.1/cxg-linux-amd64"
      sha256 "eb255b302564f23359359d75dbd04a9cac943c5bd7072361e22328876cdf8e29"
    end
    on_arm do
      url "https://github.com/Bugb-Technologies/cert-x-gen/releases/download/v1.6.1/cxg-linux-arm64"
      sha256 "c18e921072670093b8bd052862dbe463d500b9e274262fd660902ffb13aa96ce"
    end
  end

  def install
    bin.install Dir["cxg-*"].first => "cxg"
  end

  # Templates are fetched at first use, not at install time. Running
  # `cxg template update` from post_install writes outside the formula
  # prefix, which Homebrew's install sandbox denies -- it failed the
  # install rather than the download. Tell the user instead.
  def caveats
    <<~EOS
      To download vulnerability detection templates, run:
        cxg template update

      Templates will be installed to ~/.cert-x-gen/templates/
    EOS
  end

  test do
    assert_match "cxg", shell_output("#{bin}/cxg --version")
  end
end
